import * as React from "react";
import { cx } from "./cx";

export interface HoverCardProps extends React.HTMLAttributes<HTMLSpanElement> {
  trigger: React.ReactNode;
}

/** Preview panel on hover or keyboard focus. CSS only. */
export function HoverCard({ trigger, className, children, ...props }: HoverCardProps) {
  return (
    <span className={cx("rs-hover-card", className)} {...props}>
      <span tabIndex={0}>{trigger}</span>
      <span className="rs-hover-card-panel" role="tooltip">
        {children}
      </span>
    </span>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Hover card: rich preview on hover or keyboard focus ── */
.rs-hover-card{position:relative;display:inline-block}
.rs-hover-card-panel{position:absolute;top:calc(100% + 8px);left:0;z-index:170;width:260px;background:var(--bg);border:1px solid var(--divider);border-radius:var(--radius);box-shadow:0 8px 24px rgba(0,0,0,0.06);padding:14px;font-size:13px;line-height:1.55;letter-spacing:-.01em;color:var(--text-secondary);opacity:0;visibility:hidden;transition:opacity var(--duration-snap) var(--ease) var(--duration-snap),visibility var(--duration-snap) var(--ease) var(--duration-snap)}
.rs-hover-card:hover .rs-hover-card-panel,.rs-hover-card:focus-within .rs-hover-card-panel{opacity:1;visibility:visible}
